 const catalog={createdAt:new Date().toISOString(),selectionMethod:'instrumental coherent suite prompts + duration fit + full decode + loudness/peak/silence + faster-whisper speech suspicion screen; not human listening approval',loudness:'normalized -22 LUFS / -3 dBTP ceiling',downloadsUsed:18,downloadsRemaining:1,sets,legacy:assets.filter(t=>t.kind==='legacy').map(({id,title,url,duration,canonicalId})=>({id,title,url,duration,canonicalId})),assets:assets.map(({id,title,url,duration,sha256,sourceSha256,kind,canonicalId,peakDb,rmsRangeDb,silenceFraction,speechScreen})=>({id,title,url,duration,sha256,sourceSha256,kind,canonicalId,peakDb,rmsRangeDb,silenceFraction,speechScreen})),assignments:assignments.map(({musicSets,...a})=>a),duplicates:assets.filter(a=>a.id!==a.canonicalId).map(a=>({id:a.id,sameAudioAs:a.canonicalId,title:a.title}))};
