 const index=await json('background-music.json'),indexBackup=path.join(backup,'background-music.json');if(!fs.existsSync(indexBackup))fs.writeFileSync(indexBackup,index.bytes);const merged=[...index.data];for(const a of assets.filter(a=>a.kind==='new'))if(!merged.some(x=>x.url===a.url))merged.push({id:'story-library-20261015-'+a.id,title:a.title,url:a.url,createdAt:catalog.createdAt});if(merged.length!==index.data.length)await s3.send(new PutObjectCommand({Bucket,Key:'background-music.json',Body:JSON.stringify(merged),ContentType:'application/json',CacheControl:'no-cache',IfMatch:index.etag}));
