 for(let batch=0;batch<assignments.length;batch+=6){await Promise.all(assignments.slice(batch,batch+6).map(async a=>{const current=await json(a.Key);if(sha(Buffer.from(JSON.stringify(current.data.pages.map(p=>p.text))))!==a.sourceTextSha256)throw Error('Book text changed; review '+a.id);const bpath=path.join(backup,a.Key);if(!fs.existsSync(bpath))fs.writeFileSync(bpath,current.bytes);const owned=new Set(['classic-pig-20261015-01',...sets.map(s=>s.id)]);const other=(current.data.backgroundMusicSets||[]).filter(s=>!owned.has(s.id));const next={...current.data,backgroundMusicSets:[...other,...a.musicSets],backgroundMusicCues:a.musicSets[0].cues,updatedAt:new Date().toISOString()};await s3.send(new PutObjectCommand({Bucket,Key:a.Key,Body:JSON.stringify(next),ContentType:'application/json',IfMatch:current.etag}));const actual=(await json(a.Key)).data;if(JSON.stringify(actual.backgroundMusicSets)!==JSON.stringify(next.backgroundMusicSets)||JSON.stringify(actual.backgroundMusicCues)!==JSON.stringify(next.backgroundMusicCues))throw Error('Cue readback mismatch '+a.id);const omit=b=>{const {backgroundMusicSets,backgroundMusicCues,updatedAt,...rest}=b;return JSON.stringify(rest);};if(omit(actual)!==omit(current.data))throw Error('Unrelated field changed '+a.id);saved.push(a.id);}));console.log('Verified books',saved.length);}
